/// Draws icon `app` (1 WhatsApp, 2 Messenger, 3 Telegram) with its centre at (cx, cy), on a black background.
/// Returns false for any other app.
pub fn draw(s: &mut impl Surface, app: u8, cx: i32, cy: i32) -> bool {
    draw_in(s, app, cx, cy, false)
}

/// The same sign, 44 px (`SMALL`) for the top of a conversation.
pub fn draw_small(s: &mut impl Surface, app: u8, cx: i32, cy: i32) -> bool {
    draw_in(s, app, cx, cy, true)
}

pub const SMALL: i32 = 44;


fn draw_in(s: &mut impl Surface, app: u8, cx: i32, cy: i32, small: bool) -> bool {
    let (pal, data): (&[u16], &[u8]) = match (app, small) {
        (1, false) => (&WHATSAPP_PAL, &WHATSAPP),
        (2, false) => (&MESSENGER_PAL, &MESSENGER),
        (3, false) => (&TELEGRAM_PAL, &TELEGRAM),
        (1, true) => (&WHATSAPP_S_PAL, &WHATSAPP_S),
        (2, true) => (&MESSENGER_S_PAL, &MESSENGER_S),
        (3, true) => (&TELEGRAM_S_PAL, &TELEGRAM_S),
        _ => return false,
    };
    let size = if small { SMALL } else { SIZE };
    let (x0, mut y, mut i) = (cx - size / 2, cy - size / 2, 0);
    while i < data.len() {
        let n = data[i] as usize;
        i += 1;
        let mut x = x0;
        for _ in 0..n {
            let (len, p) = (data[i] as i32, data[i + 1] as usize);
            i += 2;
            if p != 0 {
                s.rect(x, y, len, 1, pal[p]);
            }
            x += len;
        }
        y += 1;
    }
    true
}

/// Paints black round the sign of `app` (a ring `m` px wide that follows its outline, tail and all), so the sign can sit
/// half on a card with a clean cut-out. False for any other app.
pub fn cutout(s: &mut impl Surface, app: u8, cx: i32, cy: i32, m: i32) -> bool {
    cutout_in(s, app, cx, cy, m, false)
}

/// A colour (RGB565) that is more than black: some channel of it is at least 3/31 bright.
fn shows(c: u16) -> bool {
    (c >> 11) >= 3 || (c >> 5) & 63 >= 6 || c & 31 >= 3
}

/// The first and last lit column (end exclusive) of each row of a sign, and its side; `None` for any other app.
fn lit_spans(app: u8, small: bool) -> Option<([(i32, i32); SIZE as usize], i32)> {
    let (pal, data): (&[u16], &[u8]) = match (app, small) {
        (1, false) => (&WHATSAPP_PAL, &WHATSAPP),
        (2, false) => (&MESSENGER_PAL, &MESSENGER),
        (3, false) => (&TELEGRAM_PAL, &TELEGRAM),
        (1, true) => (&WHATSAPP_S_PAL, &WHATSAPP_S),
        (2, true) => (&MESSENGER_S_PAL, &MESSENGER_S),
        (3, true) => (&TELEGRAM_S_PAL, &TELEGRAM_S),
        _ => return None,
    };
    let size = if small { SMALL } else { SIZE };
    let mut span = [(i32::MAX, i32::MIN); SIZE as usize];
    let (mut y, mut i) = (0usize, 0usize);
    while i < data.len() && y < size as usize {
        let n = data[i] as usize;
        i += 1;
        let mut x = 0;
        for _ in 0..n {
            let (len, p) = (data[i] as i32, data[i + 1]);
            i += 2;
            // the small signs have black and near-black colours under other numbers than 0: only a pixel that shows counts
            let lit = if small { shows(pal[p as usize]) } else { p != 0 };
            if lit {
                span[y].0 = span[y].0.min(x);
                span[y].1 = span[y].1.max(x + len);
            }
            x += len;
        }
        y += 1;
    }
    Some((span, size))
}

fn cutout_in(s: &mut impl Surface, app: u8, cx: i32, cy: i32, m: i32, small: bool) -> bool {
    let Some((span, size)) = lit_spans(app, small) else { return false };
    let (x0, y0) = (cx - size / 2, cy - size / 2);
    for row in -m..size + m {
        let (mut lo, mut hi) = (i32::MAX, i32::MIN);
        for dy in -m..=m {
            let r = row + dy;
            if !(0..size).contains(&r) || span[r as usize].0 == i32::MAX {
                continue;
            }
            let mut dx = 0;
            while (dx + 1) * (dx + 1) + dy * dy <= m * m {
                dx += 1;
            }
            lo = lo.min(span[r as usize].0 - dx);
            hi = hi.max(span[r as usize].1 + dx);
        }
        if lo < hi {
            s.rect(x0 + lo, y0 + row, hi - lo, 1, 0);
        }
    }
    true
}

/// `c` (RGB565) faded towards black by `a` of 256.
fn fade(c: u16, a: i32) -> u16 {
    let k = (256 - a) as u32;
    let (r, g, b) = ((c >> 11) as u32 & 31, (c >> 5) as u32 & 63, c as u32 & 31);
    (((r * k / 256) << 11) | ((g * k / 256) << 5) | (b * k / 256)) as u16
}

/// A smooth black rim `m` px wide round the 44 px sign of `app` (its outline, tail and all). Its edge is anti-aliased
/// against what lies under it: `under(x, y)` is that colour (RGB565), since the screen only takes opaque rects.
/// Draw the sign on top afterwards. False for any other app.
pub fn rim_small(s: &mut impl Surface, app: u8, cx: i32, cy: i32, m: i32, under: impl Fn(i32, i32) -> u16) -> bool {
    let Some((span, size)) = lit_spans(app, true) else { return false };
    let (x0, y0) = (cx - size / 2, cy - size / 2);
    // how black a pixel is (0..=256): by its distance to the nearest lit pixel, full up to m - 1/2, none from m + 1/2
    let level = |x: i32, row: i32| -> i32 {
        let mut best = i32::MAX;
        for dy in -m..=m {
            let r = row + dy;
            if !(0..size).contains(&r) || span[r as usize].0 == i32::MAX {
                continue;
            }
            let (lo, hi) = span[r as usize];
            let dx = (lo - x).max(x - (hi - 1)).max(0);
            best = best.min(dx * dx + dy * dy);
        }
        if best == i32::MAX || 4 * best >= (2 * m + 1) * (2 * m + 1) {
            0
        } else if 4 * best <= (2 * m - 1) * (2 * m - 1) {
            256
        } else {
            let d = ((best as u32) << 16).isqrt() as i32; // the distance in 1/256 px
            (m * 256 + 128 - d).clamp(0, 256)
        }
    };
    for row in -m..size + m {
        // the pixels that are surely black (up to m - 1/2 from a lit one) and the ones that may be touched at all
        let (mut slo, mut shi, mut olo, mut ohi) = (i32::MAX, i32::MIN, i32::MAX, i32::MIN);
        for dy in -m..=m {
            let r = row + dy;
            if !(0..size).contains(&r) || span[r as usize].0 == i32::MAX {
                continue;
            }
            let (lo, hi) = span[r as usize];
            let v = (2 * m - 1) * (2 * m - 1) - 4 * dy * dy;
            if v >= 0 {
                let w = (v as u32).isqrt() as i32 / 2;
                slo = slo.min(lo - w);
                shi = shi.max(hi + w);
            }
            let v = (2 * m + 1) * (2 * m + 1) - 4 * dy * dy;
            if v > 0 {
                let w = ((v - 1) as u32).isqrt() as i32 / 2;
                olo = olo.min(lo - w);
                ohi = ohi.max(hi + w);
            }
        }
        if olo >= ohi {
            continue;
        }
        let y = y0 + row;
        if slo < shi {
            s.rect(x0 + slo, y, shi - slo, 1, 0);
        }
        for x in (olo..ohi).filter(|x| slo >= shi || *x < slo || *x >= shi) {
            let a = level(x, row);
            if a > 0 {
                s.rect(x0 + x, y, 1, 1, fade(under(x0 + x, y), a));
            }
        }
    }
    true
}
